import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[11]; // Index from 1 to n, so size n+1, with 0 unused
        for (int i = 1; i <= n; i++) {
            a[i] = sc.nextInt();
        }
        // Sort the segment a[1..n]
        Arrays.sort(a, 1, n + 1);
        int median_idx = (n + 1) / 2; // 1-based index
        System.out.println(a[median_idx]);
        sc.close();
    }
}
